const body = $json.body || $json;
const callback = body.callback_query || {};
const fromId = String((callback.from && callback.from.id) || "");
const allowedUsers = (process.env.TELEGRAM_ALLOWED_USER_IDS || "").split(",").map(u => u.trim()).filter(Boolean);

// If allowedUsers is set, validate caller
if (allowedUsers.length > 0 && !allowedUsers.includes(fromId)) {
  return {
    ok: false,
    errorCode: "UNAUTHORIZED_TELEGRAM_USER",
    errorMessage: "User ID " + fromId + " is not authorized to approve content jobs.",
    callbackId: callback.id || null
  };
}

const dataStr = (callback.data || "").trim();
const parts = dataStr.split(":");
const action = parts[0] || "";
const jobId = parts[1] || "";

const validActions = ["approve", "publish_now", "schedule", "reject", "retry_assets", "cancel"];
if (!action || !jobId || !validActions.includes(action)) {
  return {
    ok: false,
    errorCode: "INVALID_CALLBACK_DATA",
    errorMessage: "Callback data must follow format <action>:<jobId>.",
    callbackId: callback.id || null
  };
}

return {
  ok: true,
  action,
  jobId,
  fromUser: callback.from ? callback.from.username || fromId : fromId,
  callbackId: callback.id || null
};

const cb = $("02 Validate Telegram Callback User").item.json;
const row = ($json && $json.job_id) ? $json : null;
if (!row) {
  return {
    ok: false,
    errorCode: "JOB_NOT_FOUND",
    errorMessage: "No job found for jobId " + cb.jobId,
    callbackId: cb.callbackId
  };
}

let targetStatus = "APPROVED";
if (cb.action === "reject") targetStatus = "REJECTED";
if (cb.action === "cancel") targetStatus = "CANCELLED";
if (cb.action === "retry_assets") targetStatus = "ASSETS_PROCESSING";
if (cb.action === "schedule") targetStatus = "SCHEDULED";

return {
  ok: true,
  jobId: row.job_id,
  action: cb.action,
  targetStatus,
  fromUser: cb.fromUser,
  callbackId: cb.callbackId
};

const st = $("05 Determine Target State").item.json;
return {
  success: true,
  jobId: st.jobId,
  status: st.targetStatus,
  message: "Telegram callback action '" + st.action + "' executed successfully by user " + st.fromUser,
  data: {
    action: st.action,
    approvedBy: st.fromUser
  },
  warnings: [],
  errors: [],
  nextAllowedActions: st.targetStatus === "APPROVED" ? ["publish_now", "schedule", "cancel"] : ["status"]
};

const j = $json || {};
const code = j.errorCode || "UNAUTHORIZED";
const message = j.errorMessage || "Telegram callback query validation failed.";
return {
  success: false,
  jobId: j.jobId || null,
  status: "FAILED",
  message,
  data: null,
  warnings: [],
  errors: [{ code, language: null, path: null, message }],
  nextAllowedActions: []
};
